@app.get("/portal/invoices/{invoice_id}/print", response_class=HTMLResponse)
def render_printable_invoice(
    request: Request,
    invoice_id: int,
    db: Session = Depends(get_db)
):
    user = get_session_user(request)
    if not user:
        return RedirectResponse(url="/login")

    invoice = db.query(Invoice).filter(Invoice.id == invoice_id, Invoice.customer_id == user.id).first()
    if not invoice:
        raise HTTPException(status_code=404, detail="Invoice not found")

    return templates.TemplateResponse("invoice_print.html", {"request": request, "invoice": invoice})
